const data = $('Get identity').all();

/**
 * Helpers
 */

function clean(value = "") {
	return value
		.replace(/<br\s*\/?>/gi, "")
		.trim();
}

function extractSector(nomRouter = "") {
	const value = clean(nomRouter);

	if (!value) return "";

	const parts = value
		.split("-")
		.map(p => p.trim())
		.filter(Boolean);

	const ignored = ["MKT", "MTD"];

	const sector = parts.find(p => !ignored.includes(p.toUpperCase()));

	if (!sector) return "";

	return sector
		.toLowerCase()
		.replace(/\s+/g, " ")
		.trim();
}

function extractOltName(nomOlt = "") {

	const value = clean(nomOlt).toUpperCase();

	if (!value) return "";

	// CDATA-BELLAVISTA
	if (value.startsWith("CDATA-")) {
		return "cData";
	}

	// SOLES_CDATA
	if (value === "SOLES_CDATA") {
		return "solesCData";
	}

	// SOLES_KINGTYPE
	if (value === "SOLES_KINGTYPE") {
		return "solesKingtype";
	}

	// SANTA BARBARA
	if (value === "SANTA BARBARA") {
		return "santaBarbara";
	}

	// CALACALI
	if (value === "CALACALI") {
		return "calacali";
	}

	// PIFO
	if (value === "PIFO") {
		return "pifo";
	}

	// POMASQUI
	if (value === "POMASQUI") {
		return "pomasqui";
	}

	// BELLAVISTA
	if (value === "BELLAVISTA") {
		return "bellavista";
	}

	// TOTORACOCHA
	if (value === "TOTORACOCHA") {
		return "totoracocha";
	}

	// Cualquier otro caso
	return value
		.toLowerCase()
		.replace(/\s+/g, " ")
		.trim();
}

function extractPon(ponOnu = "") {
	const match = ponOnu.match(/\/(\d+):/);
	return match ? match[1] : "";
}

function buildContract(row) {

	const sector = extractSector(row.nom_router);

	return {
		id: row.ruc_clpv ? row.ruc_clpv.toString() : "",
		name: row.nom_clpv,
		address: row.direccion,
		status: row.estado,

		router: {
			sector,
			olt_name: extractOltName(row.nom_olt, sector),
			pon: extractPon(row.pon_onu),
			serial: row.seriales
		}
	};
}

/**
 * Solo existe un contrato
 */
if (data.length === 1) {

	return [
		{
			json: {
				success: true,
				result: {
					found: true,
					contractNumbers: 1,
					contracts: [
						buildContract(data[0].json)
					]
				}
			}
		}
	];
}

/**
 * Filtrado cuando existen varios contratos
 */
const workflowData = $('When Executed by Another Workflow').first().json;

const address = (workflowData.address || "").toLowerCase();
const name = (workflowData.name || "").toLowerCase();
const serial = workflowData.serial;

const filteredData = data.filter(item => {

	const row = item.json;

	const itemName = (row.nom_clpv || "").toLowerCase();
	const itemAddress = (row.direccion || "").toLowerCase();
	const itemSerial = row.seriales;

	const matchesName = !name || itemName.includes(name);
	const matchesAddress = !address || itemAddress.includes(address);
	const matchesSerial = !serial || itemSerial == serial.toString();

	return matchesName && matchesAddress && matchesSerial;
});

const contracts = filteredData.map(item => buildContract(item.json));

return [
	{
		json: {
			success: true,
			result: {
				found: contracts.length > 0,
				contractNumbers: contracts.length,
				contracts
			}
		}
	}
];

